// gfx_xsdk.h - XSDK/Xenos implementation of gfx.h. Shader containers are generated by xenon/build_shaders.sh.
#pragma once
#include "xsdk/gpu.h"
#include "xsdk/shader.h"
#include "xsdk/texture.h"
#include "gfx_shader_data.h"
#include <array>

struct Prog;
namespace gfx {
static void applyDepth();
static void restoreProgram();
namespace xs {
struct TexObj {
    XsdkTexture tex = {};
    volatile uint32_t* storage = nullptr;
    Fmt fmt = RGBA8;
    Sampler sampler = {};
    bool cube = false, allocated = false;
    int samples = 0;
};
struct BufObj {
    Layout layout = L_MESH;
    volatile uint32_t* vertices = nullptr;
    volatile uint32_t* streamVertices = nullptr;
    volatile uint32_t* indices = nullptr;
    uint32_t vertexBytes = 0, streamBytes = 0, indexCount = 0;
    uint32_t lastFence = 0;
    bool usedThisFrame = false;
    struct MeshChunk { volatile uint32_t* vertices; volatile uint32_t* indices; uint32_t vertexBytes, indexCount, firstIndex; };
    std::vector<MeshChunk> chunks;
};
struct StreamArena { volatile uint32_t* memory=nullptr; uint32_t cursor=0; uint32_t fence=0; };
struct Allocation { volatile uint32_t* memory; uint32_t address, bytes; const char* tag; };
struct RetiredBuffer { volatile uint32_t* memory; uint32_t fence; bool fencePending; };
struct TargetObj { Tex color = 0; int face = -1; Tex depth = 0; };
static std::vector<TexObj> textures(1);
static std::vector<BufObj> buffers(1);
static std::vector<TargetObj> targets(1);  // handle 0 is the present buffer
static std::vector<XsdkSamplerState> samplerStates(1);
static std::array<Tex,10> bound = {};   // (unit 8: uHash, the noise texture without mip maps; 9: uCarTex, a Blender car's shading)
static Target activeTarget = 0;
static int activeW = 0, activeH = 0;
static bool dirty = false;
static bool frameActive = false;
static uint32_t lastFrameFence = 0;
static StreamArena stream[2];
static uint32_t streamFrame=1;
static constexpr uint32_t STREAM_BYTES=8u*1024u*1024u;
static constexpr uint32_t MAX_FETCH_BYTES=65535u*4u;
static constexpr uint32_t MAX_MESH_VERTICES=MAX_FETCH_BYTES/48u;
static std::vector<Allocation> allocations;
static std::vector<RetiredBuffer> retiredBuffers;
static uint64_t allocatedBytes=0, allocationCount=0;
static constexpr uint64_t XBOX_RAM_BYTES=512ull*1024ull*1024ull;
static uint32_t screenAddress = 0;
static int screenW = 0, screenH = 0;
static ::Prog* activeProgram = nullptr;

static uint32_t targetFormat(Fmt f) {
    switch (f) {
    case RGBA16F: return XSDK_TARGET_16_16_16_16_FLOAT;
    case R16F: return XSDK_TARGET_32_FLOAT;
    default: return XSDK_TARGET_8_8_8_8;
    }
}
static uint32_t textureFormat(Fmt f) {
    switch (f) {
    case R8: return XSDK_FORMAT_R8;
    case R16F: return XSDK_FORMAT_R16F;
    case RGBA16F: return XSDK_FORMAT_R16G16B16A16F;
    case DEPTH24: return XSDK_FORMAT_D24S8;
    case RGBA8: return XSDK_FORMAT_R8G8B8A8;
    case RGB8: return XSDK_FORMAT_R8G8B8A8;
    }
    return XSDK_FORMAT_R8G8B8A8;
}
static volatile uint32_t* gpuAlloc(uint32_t bytes,const char* tag) {
    const uint32_t rounded=(bytes+0xffffu)&~0xffffu;
    volatile uint32_t* p=xsdk_gpu_alloc(bytes);
    if(!p){ xsdk_log_write("gpu_alloc #%u tag=%s request=%u rounded=%u FAILED",(unsigned)++allocationCount,tag,(unsigned)bytes,(unsigned)rounded); return nullptr; }
    uint32_t address=xsdk_gpu_address(p); uint64_t end=(uint64_t)address+rounded;
    for(const auto& a:allocations){
        uint64_t ae=(uint64_t)a.address+a.bytes;
        if((uint64_t)address<ae && (uint64_t)a.address<end)
            xsdk_log_write("gpu_alloc OVERLAP tag=%s [0x%08X,0x%08llX) with %s [0x%08X,0x%08llX)",tag,(unsigned)address,(unsigned long long)end,a.tag,(unsigned)a.address,(unsigned long long)ae);
    }
    allocations.push_back({p,address,rounded,tag}); allocatedBytes+=rounded;
    xsdk_log_write("gpu_alloc #%u tag=%s request=%u rounded=%u cpu=%p gpu=0x%08X total=%llu/536870912%s",
        (unsigned)++allocationCount,tag,(unsigned)bytes,(unsigned)rounded,(const void*)p,(unsigned)address,
        (unsigned long long)allocatedBytes,allocatedBytes>XBOX_RAM_BYTES?" EXCEEDS_512MiB":"");
    return p;
}
static void gpuFree(volatile uint32_t* p) {
    if(!p)return;
    for(size_t i=0;i<allocations.size();i++) if(allocations[i].memory==p){
        allocatedBytes-=allocations[i].bytes;
        xsdk_log_write("gpu_free tag=%s gpu=0x%08X bytes=%u total=%llu",allocations[i].tag,(unsigned)allocations[i].address,(unsigned)allocations[i].bytes,(unsigned long long)allocatedBytes);
        allocations.erase(allocations.begin()+i); break;
    }
    xsdk_gpu_free(p);
}
static void reapRetiredBuffers() {
    for(size_t i=0;i<retiredBuffers.size();) {
        const auto& r=retiredBuffers[i];
        if(!r.fencePending && (!r.fence || xsdk_gpu_fence_done(r.fence))) {
            gpuFree(r.memory); retiredBuffers.erase(retiredBuffers.begin()+i);
        } else i++;
    }
}
static uint16_t half(float f) {
    uint32_t x; memcpy(&x, &f, 4);
    uint32_t sign=(x>>16)&0x8000, exp=(x>>23)&255, mant=x&0x7fffff;
    if (exp==255) return (uint16_t)(sign|0x7c00|(mant?0x200:0));
    int e=(int)exp-127+15;
    if(e>=31) return (uint16_t)(sign|0x7c00);
    if(e<=0){ if(e < -10) return (uint16_t)sign; mant=(mant|0x800000)>>(1-e); return (uint16_t)(sign+((mant+0x1000)>>13)); }
    return (uint16_t)(sign|((uint32_t)e<<10)|((mant+0x1000)>>13));
}
static XsdkSamplerState makeSampler(Sampler s) {
    XsdkSampler in = {};
    in.mag_filter = s.linear ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.min_filter = s.linear ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.mip_filter = s.mips ? XSDK_FILTER_LINEAR : XSDK_FILTER_POINT;
    in.address_u = in.address_v = s.repeat ? XSDK_ADDRESS_WRAP : XSDK_ADDRESS_CLAMP;
    in.max_anisotropy = 1; in.level_count = 1;
    XsdkSamplerState out; xsdk_texture_sampler_state(&out, &in); return out;
}
static void upload(TexObj& o, int w, int h, const void* px);
// RGBA8 mip levels below the first: each texel the average of four above. Stops at 32 texels a side (Xenos packs
// smaller levels together, which this does not attempt). Level 0 must already be uploaded.
static void uploadMips(TexObj& o, int w, int h, const void* px, int levels) {
    std::vector<uint8_t> a((const uint8_t*)px, (const uint8_t*)px + (size_t)w*h*4), b;
    for (int l = 1; l < levels; l++) {
        int nw = w/2, nh = h/2; b.resize((size_t)nw*nh*4);
        for (int y = 0; y < nh; y++) for (int x = 0; x < nw; x++) for (int c = 0; c < 4; c++)
            b[((size_t)y*nw + x)*4 + c] = (uint8_t)((a[((size_t)(2*y)*w + 2*x)*4 + c] + a[((size_t)(2*y)*w + 2*x + 1)*4 + c] + a[((size_t)(2*y + 1)*w + 2*x)*4 + c] + a[((size_t)(2*y + 1)*w + 2*x + 1)*4 + c] + 2)/4);
        for (int y = 0; y < nh; y++) xsdk_texture_upload_rows(&o.tex,(uint32_t)l,(uint32_t)y,1,b.data() + (size_t)y*nw*4,(uint32_t)nw*4);
        a.swap(b); w = nw; h = nh;
    }
    xsdk_gpu_invalidate(o.tex.address,o.tex.size_bytes);
}
static int mipLevels(Fmt f, int w, int h, bool want) { if (!want || f != RGBA8 || w != h || (w & (w - 1))) return 1; int n = 1; while ((w >> n) >= 32) n++; return n; }
static void upload(TexObj& o, int w, int h, const void* px) {
    if (!px || o.fmt == DEPTH24) return;
    const uint8_t* src = (const uint8_t*)px;
    std::vector<uint8_t> row;
    if (o.fmt == RGB8) {
        row.resize((size_t)w*4);
        for(int y=0;y<h;y++) {
            for(int x=0;x<w;x++) { row[x*4+0]=src[(y*w+x)*3+0]; row[x*4+1]=src[(y*w+x)*3+1]; row[x*4+2]=src[(y*w+x)*3+2]; row[x*4+3]=255; }
            xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,row.data(),(uint32_t)row.size());
        }
    } else if (o.fmt == R16F || o.fmt == RGBA16F) {
        int c=o.fmt==R16F?1:4; row.resize((size_t)w*c*2);
        const float* fp=(const float*)px;
        for(int y=0;y<h;y++) {
            uint16_t* hp=(uint16_t*)row.data();
            for(int i=0;i<w*c;i++) hp[i]=half(fp[y*w*c+i]);
            xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,row.data(),(uint32_t)row.size());
        }
    } else {
        uint32_t bpp=o.fmt==R8?1:4;
        for(int y=0;y<h;y++) xsdk_texture_upload_rows(&o.tex,0,(uint32_t)y,1,src+(size_t)y*w*bpp,(uint32_t)w*bpp);
    }
    xsdk_gpu_invalidate(o.tex.address,o.tex.size_bytes);
}
static void release(TexObj& o) {
    if(o.storage) gpuFree(o.storage);
    o=TexObj();
}
static void makeTexture(Tex t, int w, int h, bool tiled=true, int levels=1) {
    TexObj& o=textures[t]; Fmt fmt=o.fmt; int samples=o.samples; release(o); o.fmt=fmt; o.samples=samples;
    if(o.cube) return;
    if(!NT_SUCCESS(xsdk_texture_init(&o.tex,textureFormat(o.fmt),(uint32_t)w,(uint32_t)h,(uint32_t)levels,tiled))) return;
    o.storage=gpuAlloc(o.tex.size_bytes,"texture2d"); if(!o.storage)return;
    xsdk_texture_attach(&o.tex,o.storage);
}
static void setTarget(TargetObj& t, int w, int h) {
    activeW=w; activeH=h;
    if(!w||!h) return;
    uint32_t fmt=XSDK_TARGET_8_8_8_8;
    if(t.color) fmt=targetFormat(textures[t.color].fmt);
    XsdkColorTarget ct={fmt,0};
    uint32_t depthTile=xsdk_gpu_color_target_tiles((uint32_t)w,(uint32_t)h,fmt);
    xsdk_gpu_set_resolve_clears(true,true);
    xsdk_gpu_set_targets_samples((uint32_t)w,(uint32_t)h,t.color?std::max(1,textures[t.color].samples):1,&ct,1,depthTile);
    gfx::applyDepth();
    gfx::restoreProgram();
}
static void setScreenTarget(int w, int h) {
    const uint32_t depthTiles=xsdk_gpu_target_tiles((uint32_t)w,(uint32_t)h);
    xsdk_gpu_set_target_at((uint32_t)w,(uint32_t)h,depthTiles,0);
    gfx::applyDepth();
    gfx::restoreProgram();
}
static void resolveCurrent(uint32_t clearArgb=0xFF000000) {
    if(!dirty) return;
    TargetObj& t=targets[activeTarget];
    if(activeTarget==0) {
        // The platform resolves the active screen target at endFrame, when it owns the present address.
    } else if(t.color) {
        float clear[4]={0,0,0,0};
        xsdk_gpu_set_resolve_clears(true,true);
        XsdkTexture& destination=xs::textures[t.color].tex;
        if(xs::textures[t.color].cube && t.face>=0){
            XsdkTexture face={}; xsdk_texture_init(&face,destination.format,destination.width,destination.height,1,true);
            face.address=destination.address+(uint32_t)t.face*face.size_bytes; face.size_bytes=face.size_bytes; face.tiled=true;
            xsdk_gpu_resolve_target(0,&face,clear);
        } else xsdk_gpu_resolve_target(0,&destination,clear);
        if(t.depth && textures[t.depth].fmt==DEPTH24) xsdk_gpu_resolve_depth_texture(&textures[t.depth].tex);
    } else if(t.depth) {
        xsdk_gpu_set_depth_clear(1.0f,0);
        xsdk_gpu_resolve_depth_texture(&textures[t.depth].tex);
    }
    dirty=false;
}
static void selectTarget(Target t, int w, int h) {
    if(activeTarget!=t || activeW!=w || activeH!=h) resolveCurrent();
    activeTarget=t; activeW=w; activeH=h;
    if(t==0) { screenW=w; screenH=h; setScreenTarget(w,h); }
    else setTarget(targets[t],w,h);
}
} // namespace xs
} // namespace gfx

struct Prog {
    const FcfProgramMeta* meta=nullptr;
    XsdkShader vs={}, fs={};
    std::vector<float> vc, fc;
    void* L(const char* n) { return (void*)(has(n)?this:nullptr); }
    bool has(const char* n) const {
        if(!meta) return false;
        for(uint32_t i=0;i<meta->nvu;i++) if(!strcmp(meta->vu[i].name,n)) return true;
        for(uint32_t i=0;i<meta->nfu;i++) if(!strcmp(meta->fu[i].name,n)) return true;
        for(uint32_t i=0;i<meta->nsamplers;i++) if(!strcmp(meta->samplers[i].name,n)) return true;
        return false;
    }
    void use() {
        if(!meta) return;
        gfx::xs::activeProgram=this;
        xsdk_gpu_set_shaders(&vs,&fs);
        for(uint32_t i=0;i<meta->nvl;i++) xsdk_gpu_set_vertex_constants(meta->vl[i].reg,meta->vl[i].value,1);
        for(uint32_t i=0;i<meta->nfl;i++) xsdk_gpu_set_pixel_constants(meta->fl[i].reg,meta->fl[i].value,1);
    }
    void set(const char* n, const float* values, int count, uint32_t suppliedType) {
        if(!meta) return;
        auto put=[&](const FcfUniformMeta* a,uint32_t num,std::vector<float>& dst) {
            for(uint32_t i=0;i<num;i++) if(!strcmp(a[i].name,n)) {
                uint32_t comps=suppliedType==FCF_MAT4?16:suppliedType==FCF_VEC4?4:suppliedType==FCF_VEC3?3:suppliedType==FCF_VEC2?2:1;
                if(a[i].type==FCF_INT) comps=1;
                size_t at=a[i].offset/4;
                if(at+comps<=dst.size()) { if(suppliedType==FCF_INT) dst[at]=values[0]; else memcpy(&dst[at],values,comps*sizeof(float)); }
                return true;
            }
            return false;
        };
        bool v=put(meta->vu,meta->nvu,vc), f=put(meta->fu,meta->nfu,fc);
        if(v||f) return;
        (void)count;
    }
    void f1(const char* n,float a){set(n,&a,1,FCF_FLOAT);}
    void f2(const char* n,float a,float b){float v[2]={a,b};set(n,v,2,FCF_VEC2);}
    void i1(const char* n,int a){float v=(float)a;set(n,&v,1,FCF_INT);}
    void v3(const char* n,V3 a){float v[3]={a.x,a.y,a.z};set(n,v,3,FCF_VEC3);}
    void v4(const char* n,float a,float b,float c,float d){float v[4]={a,b,c,d};set(n,v,4,FCF_VEC4);}
    void m4(const char* n,const M4& m){set(n,m.m,16,FCF_MAT4);}
};

namespace gfx {
static void flushProgram(){
    Prog* p=gfx::xs::activeProgram; if(!p||!p->meta)return;
    if(!p->vc.empty()) xsdk_gpu_set_vertex_constants(0,p->vc.data(),(uint32_t)(p->vc.size()/4));
    if(!p->fc.empty()) xsdk_gpu_set_pixel_constants(0,p->fc.data(),(uint32_t)(p->fc.size()/4));
    for(uint32_t i=0;i<p->meta->nsamplers;i++) {
        const auto& s=p->meta->samplers[i]; gfx::Tex t=s.unit<gfx::xs::bound.size()?gfx::xs::bound[s.unit]:0;
        if(t) xsdk_gpu_set_texture(s.slot,&gfx::xs::textures[t].tex,&gfx::xs::samplerStates[t]);
    }
}
static void restoreProgram() {
    if(gfx::xs::activeProgram) { gfx::xs::activeProgram->use(); flushProgram(); }
}

static void init() { xsdk_gpu_set_depth_clear(1.0f,0); }
static int maxSamples() { return 0; }
static int maxAniso() { return 1; }

static void tex2D(Tex& t,Fmt f,int w,int h,const void* px,Sampler s) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; o.fmt=f; o.sampler=s;
    int levels=px?xs::mipLevels(f,w,h,s.mips):1;   // (only square power-of-two RGBA8 textures get a mip chain here: the lean build's noise texture)
    xs::makeTexture(t,w,h,true,levels); xs::upload(o,w,h,px); if(levels>1) xs::uploadMips(o,w,h,px,levels);
    XsdkSampler sampler={
        .mag_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.min_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,
        .mip_filter=levels>1?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.address_u=s.repeat?XSDK_ADDRESS_WRAP:XSDK_ADDRESS_CLAMP,
        .address_v=s.repeat?XSDK_ADDRESS_WRAP:XSDK_ADDRESS_CLAMP,.max_anisotropy=1,.level_count=(uint32_t)levels };
    xsdk_texture_sampler_state(&xs::samplerStates[t],&sampler);
}
static void texCube(Tex& t,Fmt f,int size,Sampler s) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; xs::release(o); o.fmt=f;o.sampler=s;o.cube=true;
    if(!NT_SUCCESS(xsdk_texture_init_cube(&o.tex,xs::textureFormat(f),(uint32_t)size,1))) return;
    o.storage=xs::gpuAlloc(o.tex.size_bytes,"texture-cube"); if(!o.storage) return; xsdk_texture_attach(&o.tex,o.storage);
    o.allocated=false; XsdkSampler sampler={.mag_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.min_filter=s.linear?XSDK_FILTER_LINEAR:XSDK_FILTER_POINT,.mip_filter=XSDK_FILTER_POINT,.address_u=XSDK_ADDRESS_CLAMP,.address_v=XSDK_ADDRESS_CLAMP,.level_count=1};
    xsdk_texture_sampler_state(&xs::samplerStates[t],&sampler);
}
static void renderbuffer(Tex& t,Fmt f,int w,int h,int n) {
    if(!t){ t=(Tex)xs::textures.size(); xs::textures.push_back({}); xs::samplerStates.push_back({}); }
    auto& o=xs::textures[t]; o.fmt=f; o.samples=n; o.sampler={}; xs::makeTexture(t,w,h,true,1);
}
static void aniso(Tex,int) {}
static void mips(Tex) {}
static void bind(int unit,Tex t) { if(unit>=0&&unit<(int)xs::bound.size()) xs::bound[unit]=t; }

static void target(Target& t,Tex color,int face,Tex depth) {
    if(!t){ t=(Target)xs::targets.size(); xs::targets.push_back({}); }
    bool rebind=xs::activeTarget==t;
    if(rebind) xs::resolveCurrent();
    xs::targets[t]={color,face,depth};
    if(rebind) xs::setTarget(xs::targets[t],xs::activeW,xs::activeH);
}
static void use(Target t,int w,int h) {
    if(t>0 && t>=xs::targets.size()) return;
    if(t==0) {
        if(xs::activeTarget!=0) xs::resolveCurrent();
        xs::screenAddress=plat::currentFrameAddress(); xs::screenW=w; xs::screenH=h;
        xs::activeTarget=0; xs::activeW=w; xs::activeH=h;
        if(xs::frameActive) xs::setScreenTarget(w,h);
        return;
    }
    xs::selectTarget(t,w,h);
}
void beginFrame(int width,int height) {
    xs::frameActive=true;
    xs::streamFrame=(xs::streamFrame+1)&1;
    auto& arena=xs::stream[xs::streamFrame];
    if(arena.fence) xsdk_gpu_wait(arena.fence,1000);
    xs::reapRetiredBuffers();
    if(!arena.memory) arena.memory=xs::gpuAlloc(xs::STREAM_BYTES,xs::streamFrame?"stream-arena-1":"stream-arena-0");
    arena.cursor=0;
    for(auto& b:xs::buffers) { b.streamVertices=nullptr; b.streamBytes=0; }
    xs::setScreenTarget(xs::screenW>0?xs::screenW:width,xs::screenH>0?xs::screenH:height);
}
static void clear(bool color,bool depth) {
    auto& t=xs::targets[xs::activeTarget];
    xsdk_gpu_set_depth_clear(1.0f,0);
    xsdk_gpu_set_resolve_clears(color,depth);
    if(color && t.color) {
        float c[4]={0,0,0,0}; xsdk_gpu_resolve_target(0,&xs::textures[t.color].tex,c);
    }
    if(depth && t.depth && xs::textures[t.depth].fmt==DEPTH24) xsdk_gpu_resolve_depth_texture(&xs::textures[t.depth].tex);
    xs::dirty=false;
    if(xs::activeTarget) xs::setTarget(t,xs::activeW,xs::activeH);
}
static void resolve(Target from,Target to,int w,int h) {
    if(xs::activeTarget!=from || to>=xs::targets.size() || !xs::targets[to].color) return;
    // Resolve the source eDRAM target directly into the destination texture before the resolve clears eDRAM.
    float c[4]={0,0,0,1}; xsdk_gpu_set_resolve_clears(true,true);
    XsdkTexture& destination=xs::textures[xs::targets[to].color].tex;
    xs::TargetObj& source=xs::targets[from];
    if(xs::textures[source.color].cube && source.face>=0){
        XsdkTexture face={}; xsdk_texture_init(&face,destination.format,destination.width,destination.height,1,true);
        face.address=destination.address+(uint32_t)source.face*face.size_bytes; face.size_bytes=face.size_bytes; face.tiled=true;
        xsdk_gpu_resolve_target(0,&face,c);
    } else xsdk_gpu_resolve_target(0,&destination,c);
    xs::dirty=false; xs::setTarget(source,xs::activeW,xs::activeH); (void)w; (void)h;
}

static void copyToGpu(volatile uint32_t* dst,const void* src,size_t bytes) {
    const uint8_t* s=(const uint8_t*)src; size_t words=(bytes+3)/4;
    for(size_t i=0;i<words;i++){ uint32_t v=0; size_t n=std::min((size_t)4,bytes-i*4); memcpy(&v,s+i*4,n); dst[i]=v; }
}
static void buffer(Buf& b,Layout l) {
    if(!b){ b=(Buf)xs::buffers.size(); xs::buffers.push_back({}); }
    xs::buffers[b].layout=l;
}
static void data(Buf b,const void* p,size_t bytes,bool streamData) {
    auto& o=xs::buffers[b]; uint32_t need=(uint32_t)((bytes+3)&~(size_t)3);
    o.streamVertices=nullptr; o.streamBytes=0;
    if(streamData) {
        auto& arena=xs::stream[xs::streamFrame];
        if(!arena.memory || arena.cursor>xs::STREAM_BYTES || need>xs::STREAM_BYTES-arena.cursor) return;
        o.streamVertices=arena.memory+arena.cursor/4; o.streamBytes=need; copyToGpu(o.streamVertices,p,bytes);
        xsdk_gpu_invalidate(xsdk_gpu_address(o.streamVertices),need); arena.cursor+=need;
    } else {
        bool detach=o.usedThisFrame;
        if(o.vertices && o.lastFence && !xsdk_gpu_fence_done(o.lastFence)) {
            if(need<=o.vertexBytes) {
                NTSTATUS wait=xsdk_gpu_wait(o.lastFence,2000);
                if(!NT_SUCCESS(wait)){ xsdk_log_write("gfx: persistent buffer fence %u wait failed 0x%08X",(unsigned)o.lastFence,(unsigned)wait); return; }
            } else detach=true;
        }
        if(need>o.vertexBytes || detach){
            uint32_t capacity=need>o.vertexBytes?std::max(256u*1024u,o.vertexBytes?o.vertexBytes*2:0u):o.vertexBytes;
            while(capacity<need && capacity<=UINT32_MAX/2) capacity*=2;
            if(capacity<need) capacity=need;
            volatile uint32_t* replacement=xs::gpuAlloc(capacity,"persistent-stream-buffer");
            if(!replacement) return;
            if(o.vertices){
                if(o.usedThisFrame) xs::retiredBuffers.push_back({o.vertices,0,true});
                else if(o.lastFence && !xsdk_gpu_fence_done(o.lastFence)) xs::retiredBuffers.push_back({o.vertices,o.lastFence,false});
                else xs::gpuFree(o.vertices);
            }
            o.vertices=replacement; o.vertexBytes=capacity; o.lastFence=0; o.usedThisFrame=false;
        }
        if(!o.vertices) return; copyToGpu(o.vertices,p,bytes); xsdk_gpu_invalidate(xsdk_gpu_address(o.vertices),o.vertexBytes);
    }
}
static void draw(Buf b,int first,int n) {
    if(n<=0)return; auto& o=xs::buffers[b]; volatile uint32_t* vertices=o.streamVertices?o.streamVertices:o.vertices; uint32_t bytes=o.streamVertices?o.streamBytes:o.vertexBytes; if(!vertices)return; uint32_t stride=o.layout==L_MESH?48:o.layout==L_PART?44:32;
    uint32_t maxVertices=xs::MAX_FETCH_BYTES/stride; maxVertices-=maxVertices%3;
    for(int done=0;done<n;){
        uint32_t count=(uint32_t)std::min((int)maxVertices,n-done); count-=count%3; if(!count) return;
        uint32_t skip=(uint32_t)(first+done)*stride, fetchBytes=count*stride; if(skip>bytes||fetchBytes>bytes-skip)return;
        xsdk_gpu_set_vertices(0,xsdk_gpu_address(vertices)+skip,fetchBytes); gfx::flushProgram(); xs::dirty=true;
        if(!o.streamVertices) o.usedThisFrame=true;
        xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST,count); done+=(int)count;
    }
}
static void mesh(Buf& b,const void* v,int nv,const uint32_t* idx,int ni) {
    if(!b){ b=(Buf)xs::buffers.size(); xs::buffers.push_back({}); }
    auto& o=xs::buffers[b]; o.layout=L_MESH;
    for(const auto& c:o.chunks){ if(c.vertices)xs::gpuFree(c.vertices); if(c.indices)xs::gpuFree(c.indices); }
    o.chunks.clear();
    const uint8_t* source=(const uint8_t*)v;
    std::unordered_map<uint32_t,uint32_t> remap; remap.reserve(65535);
    std::vector<uint8_t> vertices; vertices.reserve(65535u*48u);
    std::vector<uint32_t> indices; indices.reserve(65532);
    uint32_t firstIndex=0;
    auto flush=[&] {
        if(indices.empty()) return;
        uint32_t vb=(uint32_t)vertices.size(), ib=(uint32_t)(indices.size()*4);
        volatile uint32_t* vg=xs::gpuAlloc(vb,"mesh-chunk-vertices"); volatile uint32_t* ig=xs::gpuAlloc(ib,"mesh-chunk-indices");
        if(!vg||!ig) { if(vg)xs::gpuFree(vg); if(ig)xs::gpuFree(ig); return; }
        copyToGpu(vg,vertices.data(),vb); copyToGpu(ig,indices.data(),ib);
        xsdk_gpu_invalidate(xsdk_gpu_address(vg),vb); xsdk_gpu_invalidate(xsdk_gpu_address(ig),ib);
        o.chunks.push_back({vg,ig,vb,(uint32_t)indices.size(),firstIndex});
        remap.clear(); vertices.clear(); indices.clear();
    };
    for(int tri=0;tri+2<ni;tri+=3) {
        uint32_t add=0;
        for(int k=0;k<3;k++) if(remap.find(idx[tri+k])==remap.end()) {
            bool duplicate=false; for(int j=0;j<k;j++) if(idx[tri+j]==idx[tri+k]) duplicate=true;
            if(!duplicate) add++;
        }
        // Xenos' max-index register is 16-bit; count limits alone don't constrain referenced vertex ids.
        // This loop advances per triangle and flushes before inserting it, keeping all three rebased indices together.
        if(!indices.empty() && (remap.size()+add>xs::MAX_MESH_VERTICES || indices.size()+3>65532u)) { flush(); firstIndex=(uint32_t)tri; }
        for(int k=0;k<3;k++) {
            uint32_t old=idx[tri+k]; auto it=remap.find(old);
            if(it==remap.end()) {
                uint32_t local=(uint32_t)remap.size(); remap.emplace(old,local);
                size_t off=(size_t)old*48; vertices.insert(vertices.end(),source+off,source+off+48);
                indices.push_back(local);
            } else indices.push_back(it->second);
        }
    }
    flush(); o.indexCount=(uint32_t)ni;
}
static void drawMeshRange(Buf b,int first,int ni) {
    auto& o=xs::buffers[b]; if(ni<=0)return; uint32_t end=(uint32_t)first+(uint32_t)ni;
    for(const auto& c:o.chunks) {
        uint32_t a=std::max((uint32_t)first,c.firstIndex), z=std::min(end,c.firstIndex+c.indexCount); if(a>=z)continue;
        xsdk_gpu_set_vertices(0,xsdk_gpu_address(c.vertices),c.vertexBytes); gfx::flushProgram(); xs::dirty=true;
        xsdk_gpu_draw_indexed(XSDK_PRIMITIVE_TRIANGLE_LIST,xsdk_gpu_address(c.indices)+(a-c.firstIndex)*4,z-a,true);
    }
}
static void drawMesh(Buf b,int ni) { drawMeshRange(b,0,ni); }
static void meshChunkCheck(Buf b,const char* label,int ni) {
    const auto& chunks=xs::buffers[b].chunks; uint32_t cross=0; size_t c=0;
    for(uint32_t tri=0;tri+2<(uint32_t)ni;tri+=3) {
        while(c<chunks.size() && tri>=chunks[c].firstIndex+chunks[c].indexCount) c++;
        if(c>=chunks.size() || tri<chunks[c].firstIndex || tri+2>=chunks[c].firstIndex+chunks[c].indexCount) cross++;
    }
    xsdk_log_write("bin: cross-chunk triangles=%u mesh=%s",(unsigned)cross,label);
}
// The full-screen programs (sky, post) make their triangle from gl_VertexIndex, which xsc reads as the GPU's index
// plus a vertex base the runtime must write: float constant c0.x, as these programs have no vertex uniforms (xsdk:
// include/xsdk/xsc.h, XSDK_XSC_VERTEX_BASE). Nothing wrote it, so it held the last program's c0 (its uVP), and with a
// base of 1 the corners came out (3,-1) (-1,3) (3,3): the sky covered part of the screen, cut along a diagonal that
// moved with the camera. It is 0 for these draws.
static void drawFull(){
    gfx::flushProgram();
    if(gfx::xs::activeProgram && gfx::xs::activeProgram->meta && gfx::xs::activeProgram->meta->nvu==0) {
        static const float base[4]={0,0,0,0}; xsdk_gpu_set_vertex_constants(0,base,1);
    }
    xs::dirty=true; xsdk_gpu_draw(XSDK_PRIMITIVE_TRIANGLE_LIST,3);
}

static XsdkDepthStencilState depthState(bool test,bool write) {
    XsdkDepthStencil ds={.depth_test=test,.depth_write=write,.depth_compare=XSDK_COMPARE_LESS_EQUAL};
    XsdkDepthStencilState s; xsdk_gpu_depth_stencil_state(&s,&ds); return s;
}
static bool depthTestOn=true, depthWriteOn=true;
static XsdkDepthStencilState depthStates[4]; static bool depthReady[4]={};
static void applyDepth(){ int i=(depthTestOn?2:0)+(depthWriteOn?1:0); if(!depthReady[i]){depthStates[i]=depthState(depthTestOn,depthWriteOn);depthReady[i]=true;} xsdk_gpu_set_depth_stencil(&depthStates[i]); }
static void depthTest(bool on){ depthTestOn=on; applyDepth(); }
static void depthWrite(bool on){ depthWriteOn=on; applyDepth(); }
static void blend(Blend mode){
    static XsdkBlendState states[4]; static bool ready[4]={};
    if (!ready[mode]) {
        XsdkBlend b = {.color_source = (mode == B_PREMUL || mode == B_ADD) ? XSDK_BLEND_ONE : XSDK_BLEND_SRC_ALPHA,
                .color_dest = mode == B_OFF   ? XSDK_BLEND_ZERO
                              : mode == B_ADD ? XSDK_BLEND_ONE
                                              : XSDK_BLEND_ONE_MINUS_SRC_ALPHA,
                .color_op = XSDK_BLEND_OP_ADD,
                .alpha_source = (mode == B_PREMUL || mode == B_ADD) ? XSDK_BLEND_ONE : XSDK_BLEND_SRC_ALPHA,
                .alpha_dest = mode == B_OFF   ? XSDK_BLEND_ZERO
                              : mode == B_ADD ? XSDK_BLEND_ONE
                                              : XSDK_BLEND_ONE_MINUS_SRC_ALPHA,
                .alpha_op = XSDK_BLEND_OP_ADD,
                .write_mask = XSDK_WRITE_ALL};
        xsdk_gpu_blend_state(&states[mode], &b);
        ready[mode] = true;
    }
    xsdk_gpu_set_blend(&states[mode]);
}
static void colorWrite(bool on){
    static XsdkBlendState states[2]; static bool ready[2]={}; int i=on?1:0;
    if (!ready[i]) {
        uint32_t mask = on ? XSDK_WRITE_ALL : 0;
        XsdkBlend b = {.color_source = XSDK_BLEND_ONE,
                .color_dest = XSDK_BLEND_ZERO,
                .color_op = XSDK_BLEND_OP_ADD,
                .alpha_source = XSDK_BLEND_ONE,
                .alpha_dest = XSDK_BLEND_ZERO,
                .alpha_op = XSDK_BLEND_OP_ADD,
                .write_mask = mask};
        xsdk_gpu_blend_state(&states[i], &b);
        ready[i] = true;
    }
    xsdk_gpu_set_blend(&states[i]);
}
// Raster state: face culling and the depth offset share one xsdk state, so each change sends both.
// FCF_XSDK_CULL_FLIP: build with it if culled surfaces (terrain, building walls) vanish - the front face is then clockwise here.
static bool cullOn=false; static float offFactor=0, offUnits=0;
static void applyRaster(){
#ifdef FCF_XSDK_CULL_FLIP
    const bool cw=true;
#else
    const bool cw=false;
#endif
    XsdkRaster r={.cull=cullOn?XSDK_CULL_BACK:XSDK_CULL_NONE,.front_clockwise=cw,.depth_bias=offUnits*0.00001f,.depth_bias_slope=offFactor*0.00001f,.fill=XSDK_FILL_SOLID}; XsdkRasterState s; xsdk_gpu_raster_state(&s,&r); xsdk_gpu_set_raster(&s);
}
static void offset(float factor,float units){ offFactor=factor; offUnits=units; applyRaster(); }
static void cull(bool on){ if(on==cullOn) return; cullOn=on; applyRaster(); }
static void readRGBA(int w,int h,unsigned char* out){
    XsdkTexture fb; if(!NT_SUCCESS(xsdk_texture_init(&fb,XSDK_FORMAT_R8G8B8A8,(uint32_t)w,(uint32_t)h,1,true))) return;
    xsdk_texture_attach(&fb,xsdk_present_pixels(xs::screenAddress)); xsdk_texture_download_rows(&fb,0,0,(uint32_t)h,out,(uint32_t)w*4);
}
static void finish(){ xsdk_gpu_wait(xsdk_gpu_fence(),1000); }
static NTSTATUS waitLastFence(uint32_t timeoutMs){ return xs::lastFrameFence?xsdk_gpu_wait(xs::lastFrameFence,timeoutMs):STATUS_IO_TIMEOUT; }
static uint32_t lastFenceValue(){ return xs::lastFrameFence; }

void presentFrame(uint32_t address,int width,int height){
    xs::resolveCurrent(0xFF000000);
    xsdk_gpu_set_depth_clear(1.0f,0);
    xsdk_gpu_set_resolve_clears(true,true);
    xsdk_gpu_resolve(address,(uint32_t)width,(uint32_t)height,0xFF000000);
    xs::lastFrameFence=xsdk_gpu_fence();
    xs::stream[xs::streamFrame].fence=xs::lastFrameFence;
    for(auto& b:xs::buffers) if(b.usedThisFrame){ b.lastFence=xs::lastFrameFence; b.usedThisFrame=false; }
    for(auto& r:xs::retiredBuffers) if(r.fencePending){ r.fence=xs::lastFrameFence; r.fencePending=false; }
    xs::frameActive=false;
}

} // namespace gfx

static Prog makeProg(const char* name,const char*,const char*,const char*){
    Prog p;
    for(uint32_t i=0;i<fcf_program_count;i++) if(!strcmp(name,fcf_programs[i].name)){p.meta=&fcf_programs[i];break;}
    if(!p.meta) return p;
    if(!NT_SUCCESS(xsdk_shader_load(&p.vs,p.meta->vs,p.meta->vsBytes)) || !NT_SUCCESS(xsdk_shader_load(&p.fs,p.meta->fs,p.meta->fsBytes))) return Prog();
    if(!strcmp(name,"world")||!strcmp(name,"sky")||!strcmp(name,"water")) xsdk_log_write("gfx: %s fragment slots=%u kill=%u loops=%u",name,(unsigned)p.meta->fsSlots,(unsigned)p.meta->fsKill,(unsigned)p.meta->fsLoops);
    for(uint32_t i=0;i<p.meta->nsamplers;i++) xsdk_log_write("gfx: %s sampler %s unit=%u slot=%u",name,p.meta->samplers[i].name,(unsigned)p.meta->samplers[i].unit,(unsigned)p.meta->samplers[i].slot);
    static const XsdkVertexElement M[]={
        {.usage=XSDK_USAGE_POSITION,.usage_index=0,.format=XSDK_VERTEX_FLOAT3,.offset_bytes=0},
        {.usage=XSDK_USAGE_COLOR,.usage_index=0,.format=XSDK_VERTEX_FLOAT3,.offset_bytes=12},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=0,.format=XSDK_VERTEX_FLOAT3,.offset_bytes=24},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=1,.format=XSDK_VERTEX_FLOAT2,.offset_bytes=36},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=2,.format=XSDK_VERTEX_FLOAT1,.offset_bytes=44}};
    static const XsdkVertexElement P[]={
        {.usage=XSDK_USAGE_POSITION,.usage_index=0,.format=XSDK_VERTEX_FLOAT3,.offset_bytes=0},
        {.usage=XSDK_USAGE_COLOR,.usage_index=0,.format=XSDK_VERTEX_FLOAT2,.offset_bytes=12},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=0,.format=XSDK_VERTEX_FLOAT4,.offset_bytes=20},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=1,.format=XSDK_VERTEX_FLOAT2,.offset_bytes=36}};
    static const XsdkVertexElement U[]={
        {.usage=XSDK_USAGE_POSITION,.usage_index=0,.format=XSDK_VERTEX_FLOAT2,.offset_bytes=0},
        {.usage=XSDK_USAGE_COLOR,.usage_index=0,.format=XSDK_VERTEX_FLOAT2,.offset_bytes=8},
        {.usage=XSDK_USAGE_TEXCOORD,.usage_index=0,.format=XSDK_VERTEX_FLOAT4,.offset_bytes=16}};
    static const uint32_t meshStride[]={48}, partStride[]={44}, uiStride[]={32};
    // the vertex layout comes with the program (transform.py writes it from the program's vertex shader), so a new
    // program can't be left without one (2.22-2.23: the space track's planet and road drew nothing or garbage)
    switch(p.meta->layout){
    case FCF_LAYOUT_MESH: xsdk_shader_set_vertex_layout(&p.vs,M,5,meshStride); break;
    case FCF_LAYOUT_PART: xsdk_shader_set_vertex_layout(&p.vs,P,4,partStride); break;
    case FCF_LAYOUT_UI: xsdk_shader_set_vertex_layout(&p.vs,U,3,uiStride); break;
    default: break;   // (sky, post: drawn by drawFull, no vertex buffer)
    }
    xsdk_log_write("gfx: %s layout=%u",name,(unsigned)p.meta->layout);
    uint32_t vr=0,fr=0;
    for(uint32_t i=0;i<p.meta->nvu;i++) vr=std::max(vr,(p.meta->vu[i].offset+p.meta->vu[i].size+15)/16);
    for(uint32_t i=0;i<p.meta->nfu;i++) fr=std::max(fr,(p.meta->fu[i].offset+p.meta->fu[i].size+15)/16);
    uint32_t vlEnd=0,flEnd=0;
    for(uint32_t i=0;i<p.meta->nvl;i++) vlEnd=std::max(vlEnd,p.meta->vl[i].reg+1);
    for(uint32_t i=0;i<p.meta->nfl;i++) flEnd=std::max(flEnd,p.meta->fl[i].reg+1);
    xsdk_log_write("boot: %s registers v=%u/%u p=%u/%u literalEnds v=%u p=%u",name,vr,XSDK_FLOAT_CONSTANTS,fr,XSDK_PIXEL_CONSTANTS,vlEnd,flEnd);
    p.vc.assign(vr*4,0);p.fc.assign(fr*4,0);return p;
}
